'use strict';const $=id=>document.getElementById(id),H=MCHybrid,KEY='mc-hybrid-training-v1',colors=['#f2696d','#6bdd9b','#64bbff','#ba87f1','#f4ce70'];let lang='es',mode='merge',selected=-1,hints=[],busy=false,sound=false,upgraded=-1,hitTimer;
try{lang=localStorage.getItem('mc-language')==='en'?'en':'es'}catch{}
const words={es:{back:'← Campamento',lab:'ENTRENAMIENTO · MATCH-3 + 2048',title:'Fusiona el poder.\nLibera la energía.',lead:'Cinco colores, cristal galáctico y una decisión: ¿evolucionar la pieza o atacar ahora?',mergeTitle:'Fusionar para evolucionar',mergeRule:'Elige dos piezas vecinas del mismo color y valor. La segunda recibe el doble de valor; aparece una nueva pieza de 2 en el hueco.',matchTitle:'Combinar para atacar',matchRule:'Intercambia dos piezas vecinas para alinear al menos tres del mismo color. Sus valores se suman al ataque, aunque sean distintos. Las líneas que aparezcan tras fusionar también atacan.',tiers:'3 normal · 4 súper · 5 épico · 6+ supernova',note:'Laboratorio de prueba. No consume recursos ni modifica tu campaña o el combate anterior. Todavía no es la batalla final.',power:'Poder acumulado',highest:'Mayor valor',merges:'Fusiones',reset:'Empezar de nuevo',confirm:'¿Reiniciar solo el entrenamiento de gemas? Tu campaña se conserva.',hologram:'HOLOGRAMA DE ENTRENAMIENTO',mergeButton:'◇ Fusionar · 2 iguales',matchButton:'✦ Match · 3 en línea',hint:'Mostrar jugada',shuffle:'Reordenar sin perder valores',soundOff:'Sonido: apagado',soundOn:'Sonido: activado',saved:'Solo este entrenamiento se guarda en el navegador. Tus misiones y materiales se conservan.',selectMerge:'Toca dos vecinas del mismo color y valor.',selectMatch:'Intercambia vecinas para formar una línea.',ready:'Elige una pieza y después su vecina.',equal:'Para fusionar, las dos deben tener el mismo color y valor.',adjacent:'Las piezas deben estar una junto a la otra.',line:'Ese intercambio no forma una línea de tres.',max:'Esta gema ya ha alcanzado 2048. Úsala en un match.',fused:'¡Fusión! Nueva pieza de ',attack:'Ataque de ',powerUnit:' de poder.',combo:'Cascadas: ',hintMerge:'Fusiona las dos piezas iluminadas.',hintMatch:'Intercambia las dos piezas iluminadas.',none:'No hay jugada en este modo. Prueba el otro modo o reordena.',shuffled:'Gemas reordenadas. Conservan sus colores y valores.',shuffleFailed:'No se ha encontrado una distribución nueva. Prueba otra jugada.',healed:'Pulso vital: vida recuperada +',healFull:'La escuadra ya tiene toda su vida. Puedes guardar la habilidad.',skill:'Habilidad: ',health:'VIDA DEL ESCUADRÓN',names:['Fiery','Médico','Azul','Violeta','Comandante'],colorNames:['roja','verde','azul','violeta','dorada'],energy:'energía',row:'fila',col:'columna'},en:{back:'← Camp',lab:'TRAINING · MATCH-3 + 2048',title:'Merge the power.\nRelease the energy.',lead:'Five colors, galactic crystal and one decision: evolve your gem or attack now?',mergeTitle:'Merge to evolve',mergeRule:'Choose two adjacent gems of the same color and value. The second doubles in value; a new 2 appears in the empty slot.',matchTitle:'Match to attack',matchRule:'Swap adjacent gems to line up at least three of the same color. Their values add to the attack, even when different. Lines created by merging also attack.',tiers:'3 normal · 4 super · 5 epic · 6+ supernova',note:'Test laboratory. It does not spend resources or alter your campaign or earlier combat. This is not the final battle yet.',power:'Total power',highest:'Highest value',merges:'Merges',reset:'Start again',confirm:'Reset only gem training? Your campaign will be preserved.',hologram:'TRAINING HOLOGRAM',mergeButton:'◇ Merge · 2 equal',matchButton:'✦ Match · 3 in a line',hint:'Show a move',shuffle:'Reshuffle · keep values',soundOff:'Sound: off',soundOn:'Sound: on',saved:'Only this training is saved in this browser. Your missions and materials are preserved.',selectMerge:'Tap two neighbors of the same color and value.',selectMatch:'Swap neighbors to form a line.',ready:'Choose one gem, then its neighbor.',equal:'Merging requires the same color and value.',adjacent:'The gems must be directly next to each other.',line:'That swap does not form a line of three.',max:'This gem has reached 2048. Use it in a match.',fused:'Merged! New gem: ',attack:'Attack: ',powerUnit:' power.',combo:'Cascades: ',hintMerge:'Merge the two glowing gems.',hintMatch:'Swap the two glowing gems.',none:'No move in this mode. Try the other mode or reshuffle.',shuffled:'Gems reshuffled. Colors and values preserved.',shuffleFailed:'No new layout found. Try another move.',healed:'Vital Pulse: health restored +',healFull:'The squad is at full health. You can save the ability.',skill:'Special attack: ',health:'SQUAD HEALTH',names:['Fiery','Medic','Blue','Violet','Commander'],colorNames:['red','green','blue','violet','gold'],energy:'energy',row:'row',col:'column'}};
const t=k=>words[lang][k];function fresh(){return {board:H.fresh(),power:0,highest:2,merges:0,energy:[0,0,0,0,0],hp:1000}}
let s;try{s=JSON.parse(localStorage.getItem(KEY))}catch{}if(!s||!H.valid(s.board)||!Array.isArray(s.energy)||s.energy.length!==5||!s.energy.every(x=>Number.isFinite(x)&&x>=0&&x<=100)||![s.power,s.highest,s.merges,s.hp].every(x=>Number.isFinite(x)&&x>=0))s=fresh();
function save(){try{localStorage.setItem(KEY,JSON.stringify(s))}catch{}}function status(v){$('status').textContent=v}
function draw(){document.documentElement.lang=lang;$('language').value=lang;for(const el of document.querySelectorAll('[data-t]'))el.textContent=t(el.dataset.t);$('sound').textContent=t(sound?'soundOn':'soundOff');$('power').textContent=s.power;$('highest').textContent=s.highest;$('merges').textContent=s.merges;$('instruction').textContent=t(mode==='merge'?'selectMerge':'selectMatch');for(const name of ['merge','match']){$(name+'Mode').classList.toggle('active',mode===name);$(name+'Mode').setAttribute('aria-pressed',String(mode===name));$(name+'Mode').disabled=busy}$('board').innerHTML=s.board.map((x,i)=>'<button class="cell '+(selected===i?'selected ':'')+(hints.includes(i)?'hint ':'')+(x.value>=16?'powerful ':'')+(upgraded===i?'upgraded':'')+'" '+(busy?'disabled':'')+' style="--gx:'+((x.color%3)*50)+'%;--gy:'+(Math.floor(x.color/3)*100)+'%" onclick="pickGem('+i+')" aria-label="'+t('colorNames')[x.color]+' '+x.value+', '+t('row')+' '+(Math.floor(i/7)+1)+', '+t('col')+' '+(i%7+1)+'" aria-pressed="'+(selected===i)+'"><span class="gem"></span><span class="value">'+x.value+'</span></button>').join('');$('squad').innerHTML=t('names').map((n,i)=>'<button class="hero '+(s.energy[i]>=100?'ready':'')+'" style="--color:'+colors[i]+';--pos:'+(i*25)+'%" '+(busy||s.energy[i]<100?'disabled':'')+' onclick="ability('+i+')" aria-label="'+n+', '+s.energy[i]+' '+t('energy')+'"><div class="model"></div><b>'+n+'</b><div class="charge"><i style="width:'+s.energy[i]+'%"></i></div><small>'+s.energy[i]+' / 100 ⚡</small></button>').join('');$('squadHealth').textContent=t('health')+' · '+s.hp+' / 1000';for(const id of ['reset','hint','shuffle'])$(id).disabled=busy}
function tone(c){if(!sound)return;try{const C=window.AudioContext||window.webkitAudioContext,ctx=new C,o=ctx.createOscillator(),g=ctx.createGain();o.connect(g);g.connect(ctx.destination);o.frequency.setValueAtTime(220+c*90,ctx.currentTime);o.frequency.exponentialRampToValueAtTime(700+c*90,ctx.currentTime+.15);g.gain.setValueAtTime(.045,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.25);o.start();o.stop(ctx.currentTime+.25);o.onended=()=>ctx.close()}catch{}}
function blast(events,damage){$('beams').innerHTML=events.slice(0,7).map(e=>'<i class="beam" style="--color:'+colors[e.color]+';left:'+((e.cells[0]%7+.5)/7*100)+'%"></i>').join('');$('core').classList.remove('firing');void $('core').offsetWidth;$('core').classList.add('firing');$('hit').textContent='−'+damage;clearTimeout(hitTimer);hitTimer=setTimeout(()=>{$('hit').textContent='';$('beams').innerHTML=''},800);tone(events[0]?.color||0)}
async function pickGem(i){if(busy)return;hints=[];if(selected<0){selected=i;draw();return}if(selected===i){selected=-1;draw();return}const a=selected;selected=-1;const r=H.act(s.board,a,i,mode);if(!r.ok){status(t(r.reason));draw();return}busy=true;if(r.merged){s.merges++;s.highest=Math.max(s.highest,r.merged);upgraded=i}draw();await new Promise(resolve=>setTimeout(resolve,180));s.board=r.board;s.power+=r.damage;s.hp=Math.max(1,s.hp-6);for(const e of r.events)s.energy[e.color]=Math.min(100,s.energy[e.color]+e.charge);if(r.damage){blast(r.events,r.damage);$('feedback').textContent=t('attack')+r.damage+t('powerUnit')}else{tone(s.board[i].color);$('feedback').textContent=t('fused')+r.merged}busy=false;save();status((r.merged?t('fused')+r.merged+'. ':'')+(r.damage?t('attack')+r.damage+t('powerUnit'):'')+(r.events.length>1?' '+t('combo')+Math.max(...r.events.map(e=>e.chain)):''));draw();setTimeout(()=>{upgraded=-1},500)}
function ability(i){if(busy||s.energy[i]<100)return;if(i===1){if(s.hp===1000){status(t('healFull'));return}const add=Math.min(200,1000-s.hp);s.hp+=add;s.energy[i]=0;status(t('healed')+add);tone(i)}else{s.energy[i]=0;const damage=[240,0,260,280,350][i];s.power+=damage;blast([{color:i,cells:[3]}],damage);status(t('skill')+t('names')[i]+' · '+damage);$('feedback').textContent=t('attack')+damage+t('powerUnit')}save();draw()}
for(const m of ['merge','match'])$(m+'Mode').onclick=()=>{if(busy)return;mode=m;selected=-1;hints=[];status(t(m==='merge'?'selectMerge':'selectMatch'));draw()};$('hint').onclick=()=>{if(busy)return;const moves=mode==='merge'?H.mergePairs(s.board):H.matchMoves(s.board);if(!moves.length){status(t('none'));return}const m=moves[0];hints=[m.a,m.b];selected=-1;status(t(mode==='merge'?'hintMerge':'hintMatch'));draw()};$('shuffle').onclick=()=>{if(busy)return;const b=H.shuffle(s.board);if(b){s.board=b;selected=-1;hints=[];save();status(t('shuffled'));draw()}else status(t('shuffleFailed'))};$('reset').onclick=()=>{if(busy||!confirm(t('confirm')))return;s=fresh();selected=-1;hints=[];$('feedback').textContent='';save();status(t('ready'));draw()};$('sound').onclick=()=>{sound=!sound;if(sound)tone(2);draw()};$('language').onchange=e=>{lang=e.target.value==='en'?'en':'es';try{localStorage.setItem('mc-language',lang)}catch{}status(t('ready'));draw()};draw();status(t('ready'));save();
